/* Chroma — generador local, sin red, correo ni servicios externos. */
(() => {
  'use strict';
  const root = document.getElementById('root');
  if (!root) return;
  const KEY = 'np_palette_gallery_v1';
  const modes = { normal: 'Visión normal', deuteranopia: 'Deuteranopía', protanopia: 'Protanopía', tritanopia: 'Tritanopía' };
  const state = { colors: ['#3C83F6', '#7766F4', '#A418FB', '#7CE5F3', '#00FF9D'], mode: 'normal', notice: '', gallery: load() };

  function load() {
    try { const v = JSON.parse(localStorage.getItem(KEY) || '[]'); return Array.isArray(v) ? v : []; } catch (_) { return []; }
  }
  function persist() { try { localStorage.setItem(KEY, JSON.stringify(state.gallery.slice(0, 24))); } catch (_) { state.notice = 'No se pudo guardar en este navegador.'; } }
  function hex(v) { const s = String(v || '').trim().toUpperCase(); return /^#[0-9A-F]{6}$/.test(s) ? s : /^\w{6}$/.test(s) ? `#${s}` : '#000000'; }
  function randomColor() { return `#${Math.floor(Math.random() * 0x1000000).toString(16).padStart(6, '0').toUpperCase()}`; }
  function lum(v) { const c = hex(v).slice(1).match(/.{2}/g).map(x => parseInt(x, 16) / 255).map(x => x <= .03928 ? x / 12.92 : ((x + .055) / 1.055) ** 2.4); return .2126 * c[0] + .7152 * c[1] + .0722 * c[2]; }
  function ratio(a, b) { const x = lum(a), y = lum(b); return (Math.max(x, y) + .05) / (Math.min(x, y) + .05); }
  function textColor(v) { return lum(v) > .45 ? '#172033' : '#FFFFFF'; }
  function esc(v) { return String(v).replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c])); }
  function filter() { return state.mode === 'deuteranopia' ? 'saturate(.72) hue-rotate(18deg)' : state.mode === 'protanopia' ? 'saturate(.68) hue-rotate(-18deg)' : state.mode === 'tritanopia' ? 'saturate(.78) hue-rotate(42deg)' : 'none'; }
  function tokens() { return `:root {\n  --color-base: ${state.colors[0]};\n${state.colors.slice(1).map((c, i) => `  --color-color-${i + 2}: ${c};`).join('\n')}\n}`; }
  function swatches() { return state.colors.map((c, i) => `<div class="np-color-card"><div class="np-color-swatch" style="background:${c};color:${textColor(c)}"><span>${c}</span></div><label for="np-color-${i}">Color ${i + 1}</label><input id="np-color-${i}" class="np-color-input" data-color="${i}" type="color" value="${c}" aria-label="Seleccionar color ${i + 1}"></div>`).join(''); }
  function matrix() {
    const head = state.colors.map(c => `<th><i style="background:${c}"></i>${c}</th>`).join('');
    const rows = state.colors.map(a => `<tr><th><i style="background:${a}"></i>${a}</th>${state.colors.map(b => { const r = ratio(a, b), level = r >= 7 ? 'AAA' : r >= 4.5 ? 'AA' : 'Falla'; return `<td><b class="${level === 'Falla' ? 'bad' : 'good'}">${r.toFixed(1)}:1</b><small>${level}</small></td>`; }).join('')}</tr>`).join('');
    return `<div class="np-table-wrap"><table><thead><tr><th>Texto \\ Fondo</th>${head}</tr></thead><tbody>${rows}</tbody></table></div>`;
  }
  function gallery() {
    if (!state.gallery.length) return '<div class="np-empty">Aún no has guardado paletas.<small>Genera una combinación y pulsa «Guardar en galería».</small></div>';
    return `<div class="np-gallery-grid">${state.gallery.map(x => `<article class="np-gallery-card"><div class="np-gallery-strip">${(x.colors || []).map(c => `<span style="background:${c}"></span>`).join('')}</div><div class="np-gallery-actions"><code>${esc((x.colors || []).join(' · '))}</code><button data-delete="${esc(x.id)}" type="button">Eliminar</button></div></article>`).join('')}</div>`;
  }
  function render() {
    root.innerHTML = `<style>
      #root{min-height:100vh}.np-palette-app{min-height:100vh;padding:32px 18px 120px;background:linear-gradient(135deg,#101a36,#172b55 52%,#12203f);color:#edf4ff;font:16px Inter,system-ui,sans-serif}.np-shell{max-width:1120px;margin:auto}.np-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:28px}.np-kicker{color:#7ce5f3;font-size:.75rem;font-weight:800;letter-spacing:.14em;text-transform:uppercase}.np-head h1{margin:7px 0 8px;font-size:clamp(2rem,5vw,3.4rem);line-height:1.03;letter-spacing:-.045em}.np-head p,.np-copy{color:#b9c8e3;line-height:1.6}.np-head p{max-width:680px}.np-badge{color:#a7f3d0;border:1px solid #4b927f;background:#103e35;border-radius:999px;padding:8px 12px;font-size:.78rem;white-space:nowrap}.np-section{margin-top:20px;padding:24px;border:1px solid #ffffff1a;background:#0a1530ad;border-radius:24px;box-shadow:0 18px 60px #00000024}.np-section h2{margin:0 0 8px;font-size:1.35rem}.np-copy{margin:0 0 18px}.np-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.np-color-card label{display:block;margin:10px 0 5px;color:#aabbd8;font-size:.78rem}.np-color-swatch{min-height:118px;display:flex;align-items:flex-end;padding:12px;border-radius:16px;box-shadow:inset 0 0 0 1px #ffffff2e;font:700 .86rem ui-monospace,monospace}.np-color-input{width:100%;height:38px;padding:2px;border:1px solid #ffffff29;border-radius:10px;background:#17284a;cursor:pointer}.np-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}.np-action,.np-mode{border:0;border-radius:12px;padding:11px 16px;color:#fff;background:#2563eb;font-weight:800;cursor:pointer}.np-action.secondary{background:#334b78}.np-action.good-action{background:#059669}.np-action:active,.np-mode:active{transform:scale(.97)}.np-notice{min-height:1.25em;margin-top:14px;color:#a7f3d0;font-size:.9rem}.np-modes{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.np-mode{border:1px solid #ffffff29;color:#cbd8ee;background:#ffffff0a;border-radius:999px;padding:8px 12px;font-weight:500}.np-mode.active{border-color:#7ce5f3;color:#071b35;background:#7ce5f3}.np-preview{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));filter:${filter()}}.np-preview span{min-height:74px;display:flex;align-items:center;justify-content:center;padding:8px;font-weight:800;font-size:.78rem}.np-table-wrap{overflow-x:auto}table{width:100%;min-width:650px;border-collapse:collapse;font-size:.78rem}th,td{padding:10px;border-bottom:1px solid #ffffff17;text-align:center;color:#c6d3ea}th{color:#f1f6ff}table i{display:inline-block;width:14px;height:14px;margin-right:5px;vertical-align:-2px;border-radius:4px;box-shadow:inset 0 0 0 1px #ffffff40}.good{display:block;color:#86efac}.bad{display:block;color:#fca5a5}td small{color:#8295b6}.np-tokens{overflow:auto;margin-top:14px;padding:16px;border:1px solid #ffffff1a;border-radius:14px;background:#091329;color:#c9f8ee;white-space:pre;font:.86rem/1.6 ui-monospace,monospace}.np-gallery-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(250px,1fr));gap:12px}.np-gallery-card{overflow:hidden;border:1px solid #ffffff1a;border-radius:15px;background:#ffffff08}.np-gallery-strip{display:flex;height:54px}.np-gallery-strip span{flex:1}.np-gallery-actions{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:10px}.np-gallery-actions code{overflow:hidden;color:#b9c8e3;font-size:.67rem;text-overflow:ellipsis;white-space:nowrap}.np-gallery-actions button{border:0;background:none;color:#7ce5f3;cursor:pointer}.np-empty{padding:32px 16px;border:1px dashed #ffffff26;border-radius:16px;color:#aabbd8;text-align:center}.np-empty small{display:block;margin-top:8px;color:#7589aa}@media(max-width:700px){.np-palette-app{padding:22px 13px 136px}.np-head{display:block}.np-badge{display:inline-block;margin-top:16px}.np-section{padding:18px;border-radius:18px}.np-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.np-color-card:first-child{grid-column:span 2}.np-preview{grid-template-columns:repeat(2,minmax(0,1fr))}.np-preview span:last-child{grid-column:span 2}}
    </style><div class="np-palette-app"><div class="np-shell"><header class="np-head"><div><div class="np-kicker">Chroma · herramienta para pymes</div><h1>Generador de Paletas Corporativas</h1><p>Crea combinaciones de color, revisa su contraste y descarga variables CSS listas para usar. Todo se ejecuta localmente en este navegador.</p></div><span class="np-badge">100% local · sin registro</span></header>
    <section class="np-section"><h2>Tu combinación de colores</h2><p class="np-copy">Ajusta cada color manualmente o genera una combinación nueva. Los cambios no salen de tu dispositivo.</p><div class="np-grid">${swatches()}</div><div class="np-actions"><button class="np-action" data-action="generate" type="button">Generar combinación</button><button class="np-action good-action" data-action="save" type="button">Guardar en galería</button><button class="np-action secondary" data-action="download" type="button">Descargar CSS</button><button class="np-action secondary" data-action="copy" type="button">Copiar CSS</button></div><div class="np-notice" role="status" aria-live="polite">${esc(state.notice)}</div></section>
    <section class="np-section"><h2>Accesibilidad visual</h2><p class="np-copy">Simula deficiencias de visión de color y valida el contraste WCAG de la combinación.</p><div class="np-modes">${Object.entries(modes).map(([k,v]) => `<button class="np-mode ${state.mode === k ? 'active' : ''}" data-mode="${k}" type="button">${v}</button>`).join('')}</div><div class="np-preview">${state.colors.map(c => `<span style="background:${c};color:${textColor(c)}">${c}</span>`).join('')}</div></section>
    <section class="np-section"><h2>Matriz de contraste cruzado</h2><p class="np-copy">Ratio WCAG de cada texto sobre cada fondo. AA normal exige al menos 4,5:1 y AAA exige 7:1.</p>${matrix()}</section>
    <section class="np-section"><h2>Modo claro y oscuro automático</h2><p class="np-copy">Usa estos tokens como base para adaptar la interfaz de tu negocio a ambos modos.</p><pre class="np-tokens">${esc(tokens())}</pre></section>
    <section class="np-section"><h2>Mi galería</h2><p class="np-copy">Tus paletas guardadas en este navegador.</p>${gallery()}</section></div></div>`;
  }
  function download() { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([tokens()], { type: 'text/css' })); a.download = 'paleta-corporativa.css'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 500); state.notice = 'Archivo CSS descargado localmente.'; render(); }
  async function copy() { try { await navigator.clipboard.writeText(tokens()); state.notice = 'Variables CSS copiadas al portapapeles.'; } catch (_) { state.notice = 'No se pudo copiar automáticamente; usa Descargar CSS.'; } render(); }
  root.addEventListener('click', (e) => { const b = e.target.closest('button'); if (!b) return; const a = b.dataset.action; if (a === 'generate') { state.colors = Array.from({ length: 5 }, randomColor); state.notice = 'Nueva combinación generada localmente.'; render(); } if (a === 'save') { state.gallery = [{ id: `palette-${Date.now()}`, colors: [...state.colors] }, ...state.gallery].slice(0, 24); persist(); state.notice = 'Paleta guardada en la galería local.'; render(); } if (a === 'download') download(); if (a === 'copy') copy(); if (b.dataset.mode) { state.mode = b.dataset.mode; render(); } if (b.dataset.delete) { state.gallery = state.gallery.filter(x => x.id !== b.dataset.delete); persist(); render(); } });
  root.addEventListener('change', (e) => { const input = e.target.closest('[data-color]'); if (!input) return; state.colors[Number(input.dataset.color)] = hex(input.value); state.notice = 'Color actualizado.'; render(); });
  render();
})();
